mapper.insert:
INSERT INTO album (album_name, album_type, album_cover, introduction, album_year, company, language, sort_album_name, artist_id, song_count, update_time) SELECT s.album_name, s.album_type, s.album_cover, s.introduction, s.album_year, s.company, s.language, s.sort_album_name, s.artist_id, 0, CURRENT_TIMESTAMP FROM (VALUES
(#{item.albumName}, #{item.albumType}, #{item.albumCover}, #{item.introduction}, #{item.albumYear}, #{item.company}, #{item.language}, #{item.sortAlbumName}, #{item.artistId})
) AS s(album_name, album_type, album_cover, introduction, album_year, company, language, sort_album_name, artist_id) LEFT JOIN album t ON s.album_name = t.album_name WHERE t.album_name IS NULL

mapper.update:
UPDATE album
album_name = #{albumName}, album_type = #{albumType}, album_year = #{albumYear}, introduction = #{introduction}, company = #{company}, language = #{language}, album_cover = #{albumCover}, enrich_source = #{enrichSource}, update_time = CURRENT_TIMESTAMP
WHERE id = #{id}
